import math, random

p = [0.200, 0.021, 0.001, 0.600, 0.022, 0.008, 0.900, 0.029, 0.400, 0.0045]
assert bonferroni(p) == [False, False, True, False, False, False, False, False, False, True]
# BH: sorted p = .001 .0045 .008 .021 .022 .029 ...; thresholds .005 .010 .015 .020 .025 .030 ...
# rank 4 (.021) misses its own threshold (.020) but rank 5 and 6 pass, so ranks 1-6 are all rejected
assert benjamini_hochberg(p) == [False, True, True, False, True, True, False, True, False, True]
assert sum(benjamini_hochberg(p)) == 6 and sum(bonferroni(p)) == 2

assert bonferroni([]) == [] and benjamini_hochberg([]) == []
assert benjamini_hochberg([0.04]) == [True] and benjamini_hochberg([0.06]) == [False]
assert benjamini_hochberg([0.5, 0.6, 0.7]) == [False] * 3
assert benjamini_hochberg([0.01, 0.02, 0.03]) == [True] * 3

# 20 independent tests at alpha = 0.05
assert abs(20 * 0.05 - 1.0) < 1e-12
assert abs((1 - 0.95 ** 20) - 0.6415140775914581) < 1e-12

# BH always rejects at least everything Bonferroni rejects
r = random.Random(0)
for _ in range(500):
    ps = [round(r.random() ** 3, 4) for _ in range(r.randint(1, 25))]
    b, h = bonferroni(ps), benjamini_hochberg(ps)
    assert all(hh or not bb for bb, hh in zip(b, h))
    # rejected set is closed downwards: a rejected p implies every smaller p is rejected
    if any(h):
        cutoff = max(q for q, hh in zip(ps, h) if hh)
        assert all(hh for q, hh in zip(ps, h) if q <= cutoff)

# invalid input is rejected instead of silently counted as significant
nan = float("nan")
for fn in (bonferroni, benjamini_hochberg):
    for bad in ([nan, 0.001], [0.01, -0.1], [1.2, 0.5], [0.01, None]):
        try:
            fn(bad)
        except (ValueError, TypeError):
            pass
        else:
            raise AssertionError((fn.__name__, bad))
for bad_level in (0, -0.05, 1.5, nan):
    for fn in (bonferroni, benjamini_hochberg):
        try:
            fn([0.01, 0.02], bad_level)
        except ValueError:
            pass
        else:
            raise AssertionError((fn.__name__, bad_level))

# boundary p-values 0 and 1 are valid; with q = 1 BH rejects everything
assert benjamini_hochberg([0.0, 1.0], q=0.05) == [True, False]
assert benjamini_hochberg([0.3, 1.0], q=1) == [True, True]
assert bonferroni([0.0, 1.0]) == [True, False]

import pandas as pd

rows = [("new", 3.0)] * 50 + [("mid", 3.8)] * 150 + [("long", 4.5)] * 300
df = pd.DataFrame(rows, columns=["tenure", "score"])
pop = {"new": 0.5, "mid": 0.3, "long": 0.2}
r = poststratify(df, "tenure", "score", pop)
assert abs(r["raw_mean"] - 4.14) < 1e-12
assert abs(r["weighted_mean"] - 3.54) < 1e-12          # 0.5*3.0 + 0.3*3.8 + 0.2*4.5
assert {k: round(float(v), 6) for k, v in r["weights"].items()} == {"new": 5.0, "mid": 1.0, "long": 0.333333}
assert abs(r["kish_n"] - 174.4186046511628) < 1e-9     # 500 respondents behave like ~174

# if respondents already mirror the population, weights are all 1 and nothing changes
df2 = pd.DataFrame([("a", 2.0)] * 50 + [("b", 4.0)] * 50, columns=["g", "y"])
r2 = poststratify(df2, "g", "y", {"a": 0.5, "b": 0.5})
assert abs(r2["weighted_mean"] - r2["raw_mean"]) < 1e-12 and abs(r2["kish_n"] - 100) < 1e-9

for bad_pop in [{"new": 0.5, "mid": 0.3}, {"new": 0.5, "mid": 0.3, "long": 0.3}]:
    try:
        poststratify(df, "tenure", "score", bad_pop)
    except ValueError:
        pass
    else:
        raise AssertionError(bad_pop)

# a population stratum with respondents missing is an error, not a silent renormalisation
only_ab = pd.DataFrame([("a", 2.0)] * 10 + [("b", 4.0)] * 10, columns=["g", "y"])
for pop3 in [{"a": 0.5, "b": 0.3, "c": 0.2}]:
    try:
        poststratify(only_ab, "g", "y", pop3)
    except ValueError as e:
        assert "no respondents" in str(e)
    else:
        raise AssertionError("empty stratum accepted")

# ... but a zero-share stratum without respondents is harmless
ok = poststratify(only_ab, "g", "y", {"a": 0.5, "b": 0.5, "c": 0.0})
assert abs(ok["weighted_mean"] - 3.0) < 1e-12

# NaN scores / labels and bad shares are rejected
nan_df = df.copy(); nan_df.loc[0, "score"] = float("nan")
nan_lab = df.copy(); nan_lab.loc[0, "tenure"] = None
for bad_df in (nan_df, nan_lab, df.iloc[0:0]):
    try:
        poststratify(bad_df, "tenure", "score", pop)
    except ValueError:
        pass
    else:
        raise AssertionError("bad data accepted")
try:
    poststratify(df, "tenure", "score", {"new": 1.5, "mid": -0.3, "long": -0.2})
except ValueError:
    pass
else:
    raise AssertionError("negative shares accepted")

# an unequal-weights hand check: 3 respondents in a, 1 in b, population 50/50
h = poststratify(pd.DataFrame({"g": ["a"] * 3 + ["b"], "y": [1.0, 1.0, 1.0, 5.0]}), "g", "y", {"a": 0.5, "b": 0.5})
assert abs(h["weighted_mean"] - 3.0) < 1e-12 and abs(h["raw_mean"] - 2.0) < 1e-12
assert abs(h["kish_n"] - 3.0) < 1e-12         # weights 2/3 (x3) and 2 (x1): 4^2 / (3*4/9 + 4) = 3
